window.HANDBOOK_META = {"snapshotDate":"2026-09-05","totalTables":573,"listedTables":573,"totalReliable":3718,"measuredEdges":160,"measuredOn":"2026-08-31","keys":{"NDC9":{"name":"Drug Product Code (NDC, 9-digit)","desc":"the FDA's code for one drug product from one maker — the first 9 digits of the 11-digit NDC on a price file; the two only line up after padding to 5-4"},"UDI_DI":{"name":"Medical Device ID (UDI-DI)","desc":"the FDA's ID for one model of medical device, as printed on its label"},"FDA_APP_NO":{"name":"FDA Drug Approval # (NDA / ANDA / BLA)","desc":"the application number under which the FDA approved a drug — brand (NDA), generic (ANDA), or biologic (BLA); 13,093 in-house, no approvals file held to receive them"},"DMF_NO":{"name":"FDA Drug Master File #","desc":"the FDA's file number for a confidential manufacturing dossier a supplier keeps on file"},"HIOS_ID":{"name":"Health Plan ID (HIOS)","desc":"the marketplace ID for a health insurer, plus longer versions for one of its products or plans — the first health-plan key in-house, no partner table yet"},"BHCMIS":{"name":"HRSA Health Center ID","desc":"the grant-program ID for a federally funded community health center (the parent of its clinic sites)"},"PECOS_PAC":{"name":"PECOS Owner / Associate ID","desc":"Medicare's ID for an owner or affiliated organization in its provider-enrollment system"},"CHAIN_ID":{"name":"Nursing-Home Chain ID","desc":"Medicare's ID for the ownership group a nursing home belongs to — there is no master list, names only"},"NPDB_PRACT":{"name":"Practitioner # (NPDB)","desc":"the anonymous per-practitioner key inside the malpractice / discipline reporting bank — links reports to each other, not to a named person"},"NRC_SEQ":{"name":"Spill / Incident Report # (NRC)","desc":"the National Response Center's number for one reported spill, leak, or incident"},"NFIP_COMMUNITY":{"name":"Flood Program Community ID","desc":"FEMA's ID for a town or county that takes part in the flood insurance program; joins disasters by place, not by id"},"AQS_SITE":{"name":"Air Monitor Site ID (AQS)","desc":"the EPA's state + county + site code for one air-quality monitor; joins by place"},"WQP_SITE":{"name":"Water Monitoring Station ID","desc":"the ID for one water-quality sampling station (shares its numbering with USGS gauges)"},"FDIC_CERT":{"name":"FDIC Bank Certificate #","desc":"the FDIC's ID for an insured bank; also used for successor, direct-parent, and ultimate-parent bank pointers"},"RSSD":{"name":"Federal Reserve Bank ID (RSSD)","desc":"the Fed's ID for a bank"},"RSSD_HC":{"name":"Bank Holding-Company ID (RSSD)","desc":"the Fed's ID for the holding company that owns a bank — the holding-company master file is NOT held, so this only links tables that both point at it"},"FHFA_ID":{"name":"Home Loan Bank Member ID (FHFA)","desc":"the FHFA's ID for a member of the Federal Home Loan Bank system"},"NAIC_ID":{"name":"Insurance Company ID (NAIC)","desc":"the state insurance regulators' shared ID for an insurer — the first insurance key in the warehouse (618 insurers on the home-loan-bank membership file); no insurer master held"},"FHA_MORTGAGEE":{"name":"FHA Lender #","desc":"HUD's ID for a lender approved to make FHA-insured mortgages"},"HMDA_ARID":{"name":"Old HMDA Lender ID (pre-2018 respondent id)","desc":"the pre-2018 mortgage-lending lender ID — two number systems in one column, told apart by the agency code: bank-regulator rows are a bank certificate #, HUD rows are a tax ID. Currently unreliable as a bank join; use the official crosswalk to LEI instead"},"SEC_SERIES_ID":{"name":"SEC Fund Series ID","desc":"the SEC's ID for a registered investment fund (its share classes get class IDs)"},"SEC_FILE_NO":{"name":"SEC File #","desc":"the SEC's filing-series number for a registrant (1940-Act, 13F, and insider filings each have their own)"},"CRD":{"name":"Broker / Adviser # (CRD)","desc":"FINRA's ID for a brokerage or investment-adviser firm — held on 13F filers only; the discipline records (IAPD / BrokerCheck) are not held"},"PCAOB_ID":{"name":"Audit Firm / Engagement IDs (PCAOB)","desc":"the audit regulator's IDs for an audit firm, the company it audited, and the engagement partner"},"MIC":{"name":"Market Identifier Code (MIC)","desc":"the ISO code for a stock exchange or trading venue"},"GLEIF_RA_ID":{"name":"National Company # (via LEI record)","desc":"the home-country registry number each LEI record carries — a UK company number, a Delaware file number, etc.; only the UK registry is held to receive them"},"FARA_NO":{"name":"Foreign Agent Registration #","desc":"the Justice Department's ID for a registered foreign agent or lobbyist"},"IRS_GEN":{"name":"IRS Group Exemption #","desc":"the IRS number for a nonprofit umbrella (a church body, a chapter system) covering many local groups"},"MC_DOCKET":{"name":"Trucking Operating Authority # (MC / FF / MX)","desc":"the federal permit number for a carrier, freight forwarder, or Mexican carrier — 40% of carriers carry one"},"USDOT":{"name":"Trucking Company # (USDOT)","desc":"the federal safety ID for a trucking or bus company"},"USCG_PARTY":{"name":"Vessel Owner ID (Coast Guard)","desc":"the Coast Guard's ID for a person or company on a vessel document"},"HIN":{"name":"Hull ID Number (HIN)","desc":"the serial number stamped on a boat's hull"},"IMO":{"name":"Ship Hull Number (IMO)","desc":"the permanent international ID for a ship — survives renames and reflagging"},"MMSI":{"name":"Ship Radio ID (MMSI)","desc":"the 9-digit radio ID a ship broadcasts; 22,759 in the ship-tracking data with no owner registry held"},"CALLSIGN":{"name":"Ship Radio Call Sign","desc":"the radio call sign assigned to a vessel"},"OFAC_ENT_NUM":{"name":"Sanctions Entry # (OFAC)","desc":"Treasury's number for one entry on the sanctions list; the consolidated screening list reuses it"},"OPENSANCTIONS_ID":{"name":"OpenSanctions ID","desc":"the cross-regime ID for a sanctioned person, company, or vessel; its bag of other identifiers (Wikidata, IMO, tax ids) still needs parsing"},"OSHA_EST_ID":{"name":"OSHA Establishment ID","desc":"OSHA's ID for one workplace in the injury-summary filings — about half persist year to year"},"ORI":{"name":"Police Agency ID (ORI)","desc":"the FBI's ID for a law-enforcement agency; 4,878 present on the police-violence data, no agency master held"},"N_NUMBER":{"name":"Aircraft Tail Number (N-number)","desc":"the FAA registration mark painted on a U.S. aircraft — reissued after an aircraft leaves the registry"},"RR_CODE":{"name":"Railroad Reporting Code","desc":"the FRA's short code for a railroad company"},"FAIN":{"name":"Federal Grant Award ID (FAIN)","desc":"the ID for one federal grant or assistance award"},"PIID":{"name":"Federal Contract ID (PIID)","desc":"the ID for one federal contract; the 'parent award' version is an umbrella-contract (IDV) ID whose file is NOT held"},"CAGE":{"name":"Defense Contractor Code (CAGE)","desc":"the DoD's 5-character code for a supplier location"},"NIH_PROJECT":{"name":"NIH Project #","desc":"the core number for one NIH-funded research project"},"EIA_UTILITY_ID":{"name":"Power Utility ID (EIA)","desc":"the Energy Department's ID for an electric utility; plant owners and grid owners point at it"},"FERC_DOCKET":{"name":"FERC Docket #","desc":"the energy regulator's case number for a qualifying facility or wholesale generator — first FERC ids in-house, no FERC table held"},"HUD_CONTRACT":{"name":"HUD Section 8 Contract / Property ID","desc":"HUD's IDs for a subsidized-housing contract and the property it covers"},"USDA_RD_BORROWER":{"name":"USDA Rural Housing Borrower ID","desc":"the USDA's ID for a rural multifamily borrower"},"PECOS_ENRLMT":{"name":"PECOS Enrollment Record ID","desc":"Medicare's ID for one enrollment record (one provider in one program at one time) in its provider-enrollment system"},"EIA_PLANT_ID":{"name":"Power Plant ID (EIA / ORIS)","desc":"the Energy Department's number for one power plant; the EPA's emissions programs (eGRID, CAMPD smokestack monitors) print the same number as the ORIS code"},"AWARD_KEY":{"name":"Federal Award Unique Key","desc":"USAspending's one-string ID for a whole contract or grant (type + award number + agency); subawards point at the prime award through it"},"EIN":{"name":"Employer Tax ID (EIN)","desc":"the IRS's 9-digit number for an employer, nonprofit, or benefit-plan sponsor"}},"corrections":[{"was":"Pass 1 called the TRI facility file's FRS column dead.","now":"That column IS dead, but the same table's EPA registry-id column is live: 64,728 distinct, 99.9% resolve into the EPA facility registry. TRI <-> FRS is a solid edge (listed below)."},{"was":"Pass 1 reported ISIN empty after checking a 200-row XBRL flag table.","now":"Confirmed on the right table: 48,990 rows, 100% blank. ISIN is not held."},{"was":"Pass 1 left the nursing-home 'affiliation entity id' unverified as a possible PECOS id.","now":"It is the nursing-home chain id (635 distinct, identical to CHAIN_ID); 0% match to PECOS."},{"was":"The 08-05 catalog listed 37 ID systems as 'not held'.","now":"They are held (device IDs, malpractice bank, adverse events, Coast Guard vessels, UK ownership, retractions, single audits, EIA plant/utility ids, ...)."},{"was":"Pass 1 (08-29) said 92.5% of contract recipients resolve into the new SAM registry by UEI.","now":"That was the small recent-years contracts copy. On the full 93M-row contracts file it is 33.1% (192,931 of 582,656 UEIs) -- re-measured 2026-08-30. Older UEIs are missing from the current public SAM extract, the same gap the parent-UEI edge shows."},{"was":"The old HMDA lender id -> bank cert edge was marked SUSPECT (~half wrong).","now":"Split by agency code (2026-08-30): bank-regulator rows (agency 1-3) resolve 69.8% into FDIC certs, HUD rows (agency 7) are tax ids and resolve 40.4% into benefit-plan sponsor EINs. Name-checked 2026-08-30 (60 pairs each): bank rows 83% names agree (misses are banks renamed under the same cert), HUD rows 93%. Both split edges are SOLID; the unsplit edge stays SUSPECT."}],"traps":["2026-09-05 — MERCHANT in the p-card tables is a card-terminal string, not a merchant identity: 90,600 distinct strings collapse to 34,742 on letters only. WAL-MART #0151 and WAL-MART #3340 are separate strings; Amazon.com, AMAZON.COM, AMAZON MKTPLACE PMTS and Amazon Payments are four. Any \"distinct merchants\" count off this column is a string count.","2026-09-05 — ROWID in the Oklahoma portal tables looks like a primary key and is not one: 442,167 rows / 163,508 distinct on p-card FY2016, 668,789 / 343,102 on Vendor Payments FY2022. It restarts per monthly resource, so it collides across a package. It also silently props up drop_duplicates() in load_one — rows survive dedupe partly because ROWID differs. Ignore ROWID and FY2016 still holds 8,651 duplicate groups.","2026-09-05 — a CKAN package is a FOLDER, and its resources do not share a header. connect/portal_loader.py now pages every datastore_active resource, and pandas unions the keys, so a column present in only some resources is populated on only some rows. Measured on the 32 reloaded Oklahoma tables: 19 of 32 carry partially-filled columns. Worst is Vendor Payments FY2022 at 105 columns, 71 of them partial — PYMNT_AMT holds $7,871,848,150 over 589,381 rows and PAYMENT_AMOUNT holds $1,282,618,447 over 79,407; sum either alone and you lose 14% of the money and a whole month. Expenditure Summary at 1,957,980 rows has AGENCY_NUMBER on 50% of rows. Nine PO tables carry _2-suffixed twins sitting at 0%. The 11 p-card tables are clean at 16 columns. Before summing any portal_ table column, check its fill rate against count(*) and look for an alias twin.","2026-09-05 — comparing percentiles computed on different denominators is not a comparison. Frank's DME volume ranked on 208,605 rows read 91.3rd while his dementia share on 55,394 rows read 94.4th, which said \"sicker than he is high-volume.\" On the 3,468 rows carrying all four measures the order reverses: volume 93.9th, dementia 92.2nd, risk 92.0nd, dual 87.7th. Always re-rank on the common cohort before comparing two percentiles, and prefer the uncensored measure when one exists.","2026-09-05 — BENE_DUAL_CNT and BENE_CC_%_PCT in the DME-by-referrer file are interval-censored at 11: BENE_DUAL_CNT publishes 0 or >=11 and NEVER 1-10; the dementia share column is null on 325,834 of 381,228 rows, exactly zero on 37,000, positive on 18,394. The dementia median reads 0.0 because the middle of the distribution is deleted, not because the typical referrer has no dementia patients. Any percentile off these columns is a percentile in a distribution with a hole in it. BENE_AVG_RISK_SCRE is the uncensored alternative — non-null on 381,227 of 381,228.","2026-09-05 — FED_CMS_MEDICARE_DURABLE_MEDICAL_EQUIPMENT_..._BY_REFER: `%_SPRSN_IND is null` does NOT mean the row is whole. In the 171,372 all-flags-null cohort, 88,344 rows have TOT_SUPLR_BENES itself null and 9,253 carry a positive TOT_SUPLR_SRVCS with all three family service columns zero-filled. The DME_/POS_/DRUG_ families do not sum to TOT_: beneficiaries match on 60.5% of testable rows, suppliers 62.8%, services 78.5%. Two separate causes — a total BELOW the sum is de-duplication (a supplier or patient in two families counted once at top; happens only to suppliers and benes), a total ABOVE the sum is a masked family block (money residual is never negative, so de-dup cannot explain it). Never add the families; never compare a family column to a total column as the same population.","2026-09-03 — LIBRARY_META.CONNECT must be written with the schema quoted, \"CONNECT\" - it is a reserved word and the bare form throws a syntax error at the schema name.","2026-09-03 — sampled betweenness (k=300) on the million-node CCN-NPI graph cannot see a degree-2 bridge: the top physicians came out with IDENTICAL scores (0.00334, one sampled source's paths) at rank 233-242, and the biggest real bridge (cut 77) never appeared in the top 200. At that scale use articulation points plus block-cut-tree cut sizes for \"quiet middleman\"; betweenness only ranks hubs. Blind spot the other way: a middleman with one redundant path scores zero on cut size.","2026-09-03 — FRS_ID↔LEI in ENTITY_XREF is a star forest: one LEI, hundreds of facilities, no facility touches two LEIs. Betweenness on a star is 1.0 at the hub and 0 everywhere else; no middleman is possible by construction. Same for any parent→child crosswalk.","2026-09-03 — a fanout cutoff is not a junk filter: dropping every hospital with 500+ affiliated NPIs from the CCN↔NPI graph made the winners the hospitals with 470–490, right under the knife. Junk = blanks, zeros, '<UNAVAIL>', N/A; size alone is not junk.","2026-09-03 — FED_CMS_NPPES.EMPLOYER_IDENTIFICATION_NUMBER_EIN and PARENT_ORGANIZATION_TIN are '<UNAVAIL>' on every populated row (1,937,362 and 156,566 rows, ONE distinct value each). CMS redacts them. The columns exist, the ids do not; never build an EIN edge from NPPES.","2026-09-03 — the schema graph (CONNECT_EDGES) only knows edges the builder wired: FED_CMS_NPPES carries EIN and PARENT_ORGANIZATION_TIN columns with no EIN edge. \"Only table with both keys\" means only table with both EDGES; check information_schema.columns before saying a bridge is unique.","2026-09-03 — INTL_FR_DATA_GOUV_FULL.SPATIAL_GEOM contains 100% of US lat/lon points from nursing homes, colleges, power plants and air sites. A polygon that contains everything is a junk hub in any GEO_IN graph; it faked betweenness rank 5 before it was dropped.","2026-09-03 — FED_SAM_EXCLUSIONS_FULL_R2.NPI holds '0000000000' on 12,027 of 19,238 non-blank rows (same sentinel LEIE carries). count(distinct) is safe; count(*) where NPI is not null overcounts 2.7x.","2026-09-03 — ENTITY_XREF.FANOUT is a per-(source table, key pair) CONSTANT, not a per-value count: 6,962 on every one of 2.25M CCN→NPI affiliation rows, 821 on every FEC row. Recompute fanout with a group-by before using it as a junk-hub filter.","2026-09-03 — the date trap runs in reverse too: FED_USGS_WBD_HUC8.HUC8 is an 8-digit watershed ID (\"19010308\") that content_recon's ymd8 regex reads as a valid date and tags date_fmt. A column that looks like a date is not a date until checked, same discipline as the ID trap. Scan of all 249 ymd8/mdy8 hits found only this one naming-suspect case — narrow, not systemic — but any auto-cast pass must exclude it by name before running. See scripts/date_cast_inventory.py.","2026-09-03 — final Phase A tally, full crosswalk verified: 629 candidates checked across 4 rounds, 405 confirmed real entities, 224 confirmed noise. Every tier-1 cluster (585 after all filter fixes) has now been through at least one independent verify pass — nothing in reports/recon/gen3/ is unverified.","2026-09-03 — a common-surname case-name template (\"SMITH V. UNITED STATES\") is noise: many different unrelated litigants share the surname, confirmed across FED_COURTLISTENER_DOCKETS/OPINION_CLUSTERS/FED_SCDB. Only a distinctively-named case is a real single hit.","2026-09-03 — a bare mailing address (e.g. \"200 1ST ST SW\") clusters across tables because it's one hospital's canonical address reused for thousands of different affiliated physicians' billing address — an address-leak, not an entity. Same failure shape as the street-name leak (avenue/street names from NYC campaign filer addresses), just at building-number granularity.","2026-09-03 — \"X SERVICE STATION\" in the EPA facility tables (FRS/RCRA) is a generic facility-type label, not one franchise: SUNOCO SERVICE STATION and SHELL SERVICE STATION both verified noise, even though gen 1's original DIGEST listed them as real cross-agency hits alongside the genuinely real SHELL OIL CO. Retroactive correction — the brand name plus \"SERVICE STATION\" reads like one chain but isn't.","2026-09-03 — a hospital/care-center name is noise unless proven otherwise, even after two rounds of fixes: ST LUKES HOSPITAL, ST MARY MEDICAL CENTER, MERCY REGIONAL MEDICAL CENTER, ROLLING HILLS CARE CENTER all re-confirmed noise in round 3 — each row carries its own separate CMS Certification Number (CCN), proof of independently-run facilities, not one chain.","2026-09-03 — \"National Association\" bank names are always one entity: Wells Fargo, JPMorgan Chase, U.S. Bank, PNC, TD, KeyBank, M&T, First-Citizens, BMO, Citizens Bank all verified real. One OCC national charter, branches and SBA/PPP loans reported under it — check FED_FDIC_SOD_BRANCH_DEPOSITS' RSSDID/NAMEHCR columns to confirm one charter behind any bank name that looks generic.","2026-09-03 — international sanctions-list first names CAN be real: HAQQANI, AKHUND, SABAWI, BARZAN, ABDALLAH, QADHAFI, KONY, SADDAM all verified as the same small set of designated individuals mirrored across UK/UN/US sanctions tables, not a common-name coincidence like SMITH. Row count in the tens plus concentration on one regime/list family is the tell; hundreds of rows spread across unrelated sanctions programs (MOHAMED, ALI, AHMED) is still noise.","2026-09-03 — a generic-sounding multi-word name is NOT automatically noise: Knights of Columbus, Rotary International, Kaiser Foundation Hospitals, American Legion Auxiliary all verified real — one chartered parent org with many local chapters/facilities. The tell: check if the source tables imply one franchising body (IRS BMF nonprofit charters) vs many independent locals (CMS hospital directory) — ST LUKES HOSPITAL and MEMORIAL HOSPITAL are the independent-locals case, still noise.","2026-09-03 — a THIRD who-column noise type, biggest yet: category/classification fields (OSHA injury type, body part, job title, political party) get tagged \"who\" same as name columns. 54 of 169 phase-A-round-2 verify hits were this — STRAIN, ATTORNEY, PHYSICIAN, DEMOCRAT, KITCHEN all read as \"cross-table entities\" until checked.","2026-09-03 — county names leak past the \" COUNTY\" suffix filter through columns like CZ_NAME (NOAA), CNTY_NM2KX/CURCNTY_NM (HUD), and XC_CENSUS_CB_COUNTY's own NAME column, where the value is the bare county name (\"Jackson\") with no \"COUNTY\" suffix to catch.","2026-09-03 — generic institutional names collide exactly like surnames: ST LUKES HOSPITAL in FED_CMS_HOSPITAL_COMPARE is many unrelated hospitals (confirmed via FACILITY_ID and a separate ROR registry ID per hospital), sitting next to MEMORIAL HOSPITAL, HOLY CROSS HOSPITAL, ST JOSEPH MEDICAL CENTER, MERCY MEDICAL CENTER, COMMUNITY HOSPITAL — all unverified same-name collisions still sitting uncaveated in gen 1's DIGEST.md \"same name, many tables\" table.","2026-09-03 — the surname leak rides columns the *_LAST_NAME filter never catches: NAME_LAST, NAME_FIRST, FILER_NAML/FILER_NAMF, a bare column named LAST, RNDRNG_PRVDR_LAST_ORG_NAME (name and org mixed in one field), CASE_NAME_SHORT, PLT/DEF party fields, FAMILY_NAME. Any \"who\" column pull needs this list too, not just *_LAST_NAME.","2026-09-03 — cross-table name-matching on a bare single word is 8% real (2 of 25 verified: TESLA, PACIFICORP), not an entity signal. Common surnames/first names (JOHNSON, SMITH, THOMAS...) cluster across physician/judge/legislator/lobbyist tables because thousands of unrelated people share the name — row count in the hundreds of thousands is the tell. Multi-word names cleared 92% real (11 of 12) in the same test; trust those, verify single words one by one.","2026-09-02 — FED_CMS_OPEN_PAYMENTS APPLICABLE_MANUFACTURER_OR_APPLICABLE_GPO_MAKING_PAYMENT_ID is a 12-digit numeric id (100000000xxx); any 'PAYMENT' name-match that sums it reads $1.5 quadrillion. Column name says PAYMENT, content says id.","2026-09-02 — ArcGIS PORTAL_ARC_ date columns land as epoch MILLISECONDS with a trailing '.0' (e.g. 1555977600000.0), often under names like LASTCHANGE or ST_REVIEW; a bare sum reads as trillions. Detect 13-digit values, divide by 1000, dateadd from 1970.","2026-09-02 — _INGESTED_AT reads year ~56,660,000 on at least 7 tables (EPA CAMPD, GUDID x2, GLEIF REPEX, FMCSA census, SAM entity, USCG vessels): loaders stamped epoch microseconds as seconds. year() on it throws; never trust _INGESTED_AT as a date without a range check.","2026-09-02 — PORTAL_ landing tables never exceed 10,000 rows; 169 of 1,563 sit at exactly 10,000, the scraper's page cap. Those 169 are samples, not datasets; any count or sum on them is a floor.","2026-09-01 — FED_HOUSE_DISBURSEMENTS.AMOUNT is TEXT and 6 rows hold column-shifted junk from embedded commas; bare sum() throws — always try_to_number. SOD_QUARTER has 42 spellings in 6 styles; parse with care.","2026-09-01 — FINANCE__FED_FEC_COMMITTEES_DIM.CYCLE is null on 55% of rows (the cm_multicycle fills); filtering or faceting on CYCLE silently drops the majority of the dimension.","2026-09-01 — FED_FEC_COMMITTEES repeats 16,943 ids across cycles with NO cycle column; a raw name join inflates itoth money 2.14x. Join FINANCE__FED_FEC_COMMITTEES_DIM instead; 14.1% of real money rows (270,519) carry IS_AMBIGUOUS=true — that id's type/party/name conflicts across cycles, filter or caveat before any spend-by-attribute chart. (First shipped version flagged only cm rows, 0.07% — wrap skeptic caught it, fixed same day.)","2026-09-01 — FED_HOUSE_FD_PTR_INDEX.DOCID is NOT unique: the Clerk re-lists amendments in every year's zip (41,883 rows, 41,860 distinct). NO natural key exists: DOCID+INDEX_YEAR also fans out (18 exact-dupe row groups); dedup on hash(*). Only DOCID 9110829 legitimately spans years.","2026-09-01 — FED_HOUSE_DISBURSEMENTS ships SUBTOTAL ROWS INLINE: 371K rows (7.6%) with DESCRIPTION LIKE '%TOTALS%' hold $48.4B of the $64.5B naive sum. Filter them out or every dollar total is ~4x reality; detail-only ≈ $1.5B/yr matches the House appropriation.","2026-09-01 — FED_USASPENDING_CONTRACTS_FULL is exactly 20,000,000 rows — a cap, superseded by _R2 (93M, wired); ASSISTANCE_FULL 19.9M unverified either way.","2026-09-01 — count parity is not coverage when the source prunes: GLEIF drops ended relationships, so a BIGGER new vintage still lost July's dead links. Rescued to RAW.RETIRED.INTL_GLEIF_RR_VINTAGE_20260731.","2026-09-01 — FED_FCC_LICENSING.EIN is 100% empty string, 1.69M rows; detect_key fires on names. Count distinct before calling any column a key.","2026-09-01 — FED_FEC_COMMITTEE_TO_COMMITTEE is 93% 15J earmark memos with MEMO_CD='X'; summing with itcont double-counts the same dollar under different CMTE_ID and SUB_ID. Filter MEMO_CD <> 'X' first.","2026-09-01 — the watermark lies BOTH ways: fed_cms_tic_mrf and fed_cms_hpt_enforcement have watermark rows and zero landed data. Watermark membership proves nothing in either direction.","2026-09-01 — \"never landed\" by registry-vs-watermark SOURCE_ID join lied twice (FEC contributions, OpenSanctions): registry doubles and missing watermark credit both fake absence. LIKE-search LANDING table names before queuing any load.","2026-08-30 — typing-layer tests query live marts but carried no snowflake marker until today; unmarked tests can burn credits from a plain pytest run.","2026-08-30 — \"1,121\" is the hard-ID edge count in lab_map facts, NOT the test count. The two got copy-crossed once already.","2026-08-30 — portal_recon/ looks dead by import scan; connect/keys.py sys.path-imports its tagger by bare file name. Grep file names before retiring a folder.","2026-08-31 — identical row counts ≠ identical tables: hash before dropping, always. But raw HASH_AGG lies the other way too: the 8 ICIJ \"different vintage\" copies were the SAME snapshot with different blank spellings ('', NULL, 'NA', 'None', 'N/A', 'n/a') — blank-normalize before hashing or every loader pair \"differs\". Verdict: reports/row1/icij_vintage_verdict_2026-08-31.md.","2026-08-31 — the timeline rollup tables freeze the planned/actual tag at build time; it ages past current_date. Guard green also ≠ TIMELINE schema clean — nothing walks warehouse→registry.","2026-08-31 — USAspending landing tables carry case-sensitive lowercase and digit-leading column names; unquoted SQL resolves uppercase and misses.","2026-08-31 — some loaders write audit columns UNPREFIXED (LEIE: INGESTED_AT not _INGESTED_AT); check before referencing.","2026-08-31 — Part D prescriber-drug has NO year column; one load run = one data year (DY22), not a series.","2026-08-31 — dbt test warn ≠ small: this run's 246 warns hide 99.4M failing rows.","2026-08-31 — the name-matcher's first-12-chars rule passes UNIVERSITY OF MICHIGAN = UNIVERSITY OF MISSOURI; ~12% false-positive on generic org names.","2026-08-31 — FDA_DT is the receipt date; it smears quarter-file boundaries. Reconcile FAERS by run id, never by event-date histogram.","2026-08-31 — checkpoint-sum = landing-count proves nothing about never-attempted files: both sides are zero. 13F missed 7 of 53 zips while summing exactly.","2026-08-31 — LEIE UPIN column holds empty strings, not NULLs; count() without nullif(trim()) overcounts 14x.","2026-08-31 — SOURCE_REGISTRY.INCLUDE is a 'Y'/'N' STRING; Python truthiness counts 'N' as true.","2026-08-31 — landing table name = UPPER(SOURCE_ID) is broken warehouse-wide; name-only registry↔landing joins fabricate hundreds of false orphans both ways.","2026-08-31 — zip loads keep only the LARGEST member per zip (08_bulk_ingest.sql:179); a count that's a multiple of the publisher's split size is the smell, but partial last chunks make totals non-round. 18 zip specs ride this path.","2026-08-30 — the warehouse query log stores SQL text, not shell commands; price by table/statement pattern, not by script name. 500 rows = the cap, not a count.","2026-08-30 — the scripts door logs in as ACCOUNTADMIN; a wrong command has no safety net."],"place":{"measuredOn":"2026-08-30","axisTables":{"state":230,"city":175,"zip":125,"address":115,"county":80,"facility_site":54,"coordinates":52,"country":50,"region":41,"fips":33,"metro":20,"cong_district":14,"geometry":4,"airport_port":3,"watershed":1},"axisLabel":{"state":"state","zip":"ZIP code","county":"county","fips":"FIPS / GEOID code","coordinates":"lat / lon","city":"city","address":"street address","country":"country","metro":"metro area","cong_district":"congressional district","census_tract":"census tract","facility_site":"site / place name","region":"region","airport_port":"airport / port","geometry":"map shape","watershed":"watershed"},"tables":338},"time":{"measuredOn":"2026-08-20","grainTables":{"day":309,"month":13,"quarter":15,"year":195},"meaningTables":{"happened":230,"reported":155,"span_end":123,"decided":81,"span_start":79,"unlabeled":42,"unclear":11},"tables":452},"newTables":353,"noIdTables":353,"excluded":{"refreshed_on":"2026-09-05","edges_measured_on":"2026-08-28","zip_edges":2522,"portal_tables":1563,"why":"ZIP and NAME@ZIP edges identify a postcode, not a party. 1563 PORTAL_ tables are landed but not wired into CONNECT."},"goneTables":["FED_FAA_REGISTRY","FED_NCUA_CALL_REPORTS"],"edgesMeasuredOn":"2026-08-28","liveRowsFrom":"2026-09-05"};
